    isBrowser: false,
    favorite: false
  },
  computed: {
    article () { return useArticleStore(this.$pinia).article || {} },
    recommendations () { return useArticleStore(this.$pinia).recommendations }
  },
  onLoad (query) {
    if (!this.$ssrContext) this.loadArticle(query.id)
  },
  mounted () {
    this.isBrowser = typeof window !== 'undefined'
  },
